def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MIN_SUPPLY = 15
    MAX_SUPPLY = 25

    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    if budget <= 0:
        return 0.0

    alive = []
    for oid, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append((oid, opp))

    if not alive:
        return float(min(budget, DAILY_SALARY * 0.35))

    est_competitors = 1
    if supply < WATER_REQ * 2:
        est_competitors = 2
    else:
        est_competitors = int(max(1, round(supply / float(WATER_REQ))))

    prev_bids = []
    threat_scores = []
    for oid, opp in alive:
        prev = opp.get('previous_trace') or {}
        pbid = prev.get('bid')
        if pbid is not None:
            prev_bids.append(float(pbid))
        score = 0.0
        if opp.get('budget', 0) >= 500:
            score += 2.0
        if opp.get('hp', 0) >= 7:
            score += 1.0
        if pbid is not None:
            if pbid >= 130:
                score += 3.0
            elif pbid >= 80:
                score += 2.0
            elif pbid > 0:
                score += 1.0
        if opp.get('no_water_days', 0) >= 2:
            score += 2.0
        threat_scores.append(score)

    high_prev = max(prev_bids) if prev_bids else 0.0
    avg_prev = sum(prev_bids) / len(prev_bids) if prev_bids else 0.0
    strong_opp = 0
    for s in threat_scores:
        if s >= 4.0:
            strong_opp += 1

    urgent = hp <= 3 or no_water_days >= 2
    pressured = hp <= 5 or no_water_days >= 1
    tight_supply = supply < WATER_REQ * 2
    abundant = supply >= WATER_REQ * 2

    if urgent:
        bid = max(138.0, high_prev + 3.0, DAILY_SALARY * 1.9)
    elif tight_supply and strong_opp >= 2:
        bid = max(136.0, high_prev + 2.0)
    elif tight_supply and strong_opp >= 1:
        bid = max(118.0, avg_prev + 4.0)
    elif pressured and strong_opp >= 2:
        bid = max(128.0, high_prev + 1.5)
    elif abundant and hp >= 7 and no_water_days == 0:
        bid = DAILY_SALARY * 0.45
    elif strong_opp >= 2:
        bid = max(92.0, avg_prev * 0.78)
    elif strong_opp == 1:
        bid = max(72.0, avg_prev * 0.7)
    else:
        bid = DAILY_SALARY * 0.55

    if day >= 8:
        if hp <= 5:
            bid = max(bid, 125.0)
        else:
            bid = max(bid, 85.0)

    reserve = 0.0
    if hp >= 6 and day <= 6:
        reserve = DAILY_SALARY * 1.2
    elif hp >= 4:
        reserve = DAILY_SALARY * 0.6

    max_affordable = max(0.0, budget - reserve)
    if urgent:
        max_affordable = budget

    bid = min(bid, max_affordable if max_affordable > 0 else budget)
    bid = min(bid, budget)
    bid = max(0.0, bid)

    return float(round(bid, 2))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 150
    EPISODE_DAYS = 10

    alive_opponents = [o for o in opponents_status.values() if o['alive']]

    if not alive_opponents:
        return min(my_status['budget'], DAILY_SALARY * 0.1)

    # Determine initial bid based on my status
    if my_status['hp'] <= 2 or my_status['no_water_days'] > 0:
        base_bid = DAILY_SALARY * 0.95
    elif my_status['hp'] <= 4:
        base_bid = DAILY_SALARY * 0.75
    else:
        base_bid = DAILY_SALARY * 0.5

    # Adjust bid based on overall supply and demand
    total_water_demand = WATER_REQ
    for opp in alive_opponents:
        total_water_demand += opp['water_requirement']

    if day_context['supply'] < total_water_demand:
        base_bid += DAILY_SALARY * 0.15
    elif day_context['supply'] >= total_water_demand + WATER_REQ * 2:
        if my_status['hp'] > 4:
            base_bid -= DAILY_SALARY * 0.1

    # Adjust bid based on opponents' previous bids (yesterday's trace)
    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])

    if yesterday_bids:
        highest_prev_bid = max(yesterday_bids)

        if highest_prev_bid >= DAILY_SALARY * 0.8:
            base_bid = max(base_bid, highest_prev_bid + 1.0)
        elif highest_prev_bid < DAILY_SALARY * 0.3:
            if my_status['hp'] > 2 and my_status['no_water_days'] == 0:
                base_bid = min(base_bid, highest_prev_bid + 5.0)

    # Final bid constraints
    final_bid = min(my_status['budget'], base_bid)

    if my_status['hp'] <= 2 or my_status['no_water_days'] > 0:
        final_bid = min(final_bid, DAILY_SALARY * 1.1)
    else:
        final_bid = min(final_bid, DAILY_SALARY * 1.0)

    if final_bid <= 0.0 and my_status['budget'] > 0:
        final_bid = 1.0

    return final_bid

